'use strict';
const $=id=>document.getElementById(id);
let fields={},current=null,busy=false,dirty=false,poll=null;
const states={uploaded:'已上传，尚未识别',recognizing:'正在识别，请稍候…',needs_confirmation:'识别完成，等待你核对',confirmed:'已确认保存',failed:'识别失败，可手工填写',interrupted:'识别中断，可手工填写'};
function message(text){$('notice').textContent=text;$('form-notice').textContent=text;}
async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{let headers={};if(body){headers={'Content-Type':'application/json','X-Review-Token':(await api('/api/session')).token};}const res=await fetch(path,{method:body?'POST':'GET',headers,body:body?JSON.stringify(body):undefined,signal:controller.signal});const result=await res.json();if(!res.ok)throw new Error(result.error||'请求失败');return result;}catch(e){if(e.name==='AbortError'||e instanceof TypeError)throw new Error('本机服务连接失败或超时，请保留本页，恢复服务后查看记录；不会自动重试识别。');throw e;}finally{clearTimeout(timer);}}
function controls(){const locked=current?.status==='confirmed'||current?.status==='recognizing';$('upload').disabled=busy;$('recognize').disabled=busy||!current||current.status!=='uploaded';for(const node of $('confirm-form').elements)node.disabled=busy||locked;}
async function history(select){const result=await api('/api/metrics');fields=result.fields;$('history').replaceChildren(new Option('选择记录',''));for(const r of result.records)$('history').add(new Option((r.confirmation?.title||'未命名截图')+' · '+states[r.status]+' · '+new Date(r.created_at).toLocaleString('zh-CN'),r.id));$('history').value=select||'';}
function render(record){current=record;dirty=false;clearTimeout(poll);$('editor').hidden=false;$('original').src='/api/metrics/image?id='+record.id;$('original-link').href=$('original').src;$('recognition-state').textContent=states[record.status]+(record.error?'：'+record.error:'');$('raw').textContent=JSON.stringify(record.candidate||{},null,2);const c=record.confirmation;
  $('title').value=c?.title||record.candidate?.title_text||'';$('sample').value=c?.sample_id||'';$('observed').value=c?new Date(new Date(c.observed_at).getTime()+8*3600000).toISOString().slice(0,16):'';$('scope').value=c?.scope||'unknown';$('note').value=c?.note||'';$('reviewed').checked=!!c;
  $('metric-fields').replaceChildren();for(const [key,label] of Object.entries(fields)){const wrap=document.createElement('label');wrap.className='field';const text=document.createElement('span');text.textContent=label;const input=document.createElement('input');input.id='value-'+key;input.maxLength=40;input.placeholder='未知请留空';input.value=c?.metrics[key]??record.candidate?.metrics[key]??'';wrap.append(text,input);$('metric-fields').append(wrap);}
  $('saved-summary').textContent=c?'已保存：'+c.title+'。统计时间 '+new Date(c.observed_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'。未知字段仍保留为空。'+(c.approximate_fields.length?' 含“万／亿”缩写的字段按展示值换算，精度受原图限制。':''):'';
  if(record.candidate?.warnings?.length)message(record.candidate.warnings.join('\n'));controls();if(record.status==='recognizing')poll=setTimeout(()=>load(record.id),1500);
}
async function load(id){try{render(await api('/api/metrics/detail?id='+encodeURIComponent(id)));}catch(e){message(e.message);}}
$('confirm-form').oninput=()=>{dirty=true;};
$('history').onchange=async()=>{const id=$('history').value;if(!id)return;if(dirty&&!confirm('有未保存的核对内容，确定切换吗？')){$('history').value=current.id;return;}message('');await load(id);};
$('upload').onclick=async()=>{if(busy)return;const file=$('file').files[0];if(!file||file.size>10*1024*1024){message('请先选择不超过 10MB 的 PNG/JPEG 截图');return;}if(dirty&&!confirm('有未保存的核对内容，确定上传另一张吗？'))return;busy=true;controls();try{message('正在保存原图…');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('图片读取失败'));reader.readAsDataURL(file);});const record=await api('/api/metrics/upload',{image_base64:data});await history(record.id);render(record);message('原图已保存。可以点击识别，也可以直接对照填写。');}catch(e){message(e.message);}finally{busy=false;controls();}};
$('recognize').onclick=async()=>{if(busy||!current)return;if(dirty&&!confirm('识别结果会替换当前未保存的填写内容，确定继续吗？'))return;busy=true;controls();try{const record=await api('/api/metrics/recognize',{id:current.id});message('已启动一次识别。关闭页面不会自动重试。');render(record);}catch(e){message(e.message);}finally{busy=false;controls();}};
$('confirm-form').onsubmit=async event=>{event.preventDefault();if(busy||!current)return;const metrics=Object.fromEntries(Object.keys(fields).map(key=>[key,$('value-'+key).value.trim()||null]));const confirmation={reviewed:$('reviewed').checked,title:$('title').value.trim(),sample_id:$('sample').value,observed_at:$('observed').value+':00+08:00',scope:$('scope').value,metrics,note:$('note').value.trim()};busy=true;controls();try{const record=await api('/api/metrics/confirm',{id:current.id,confirmation});render(record);await history(record.id);message(record.candidate?'已确认并保存数据。原图、机器识别和人工修订均已留档。':'已确认并保存手工核对数据，原图已留档。');}catch(e){message(e.message);}finally{busy=false;controls();}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{await history();const samples=await api('/api/samples');for(const sample of samples.samples||[])$('sample').add(new Option(sample.sample_id,sample.sample_id));const id=new URLSearchParams(location.search).get('id');if(id){$('history').value=id;await load(id);}}catch(e){message(e.message);}})();
